-- 0086_alerts_int_classes: widen biz.alerts.access_class and biz.alerts.needs from
-- smallint/smallint[] to integer/integer[] to match biz.access_classes (which surpassed
-- 32,767). Idempotent and safe when biz_page.alerts already exists.
DO $$ DECLARE v text; BEGIN IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'biz' AND table_name = 'alerts' AND ((column_name = 'access_class' AND udt_name <> 'int4') OR (column_name = 'needs' AND udt_name <> '_int4'))) THEN IF to_regclass('biz_page.alerts') IS NOT NULL THEN SELECT pg_get_viewdef('biz_page.alerts'::regclass) INTO v; DROP VIEW biz_page.alerts; END IF; ALTER TABLE biz.alerts ALTER COLUMN access_class TYPE integer; ALTER TABLE biz.alerts ALTER COLUMN needs TYPE integer[]; IF v IS NOT NULL THEN EXECUTE 'CREATE VIEW biz_page.alerts WITH (security_barrier = true) AS ' || v; IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'plx_page_reader') THEN GRANT SELECT ON biz_page.alerts TO plx_page_reader; END IF; END IF; END IF; END $$;
